INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/1, /*action_type*/2, /*action_param*/1000, /*face_icon_type*/2, /*text_1*/'训练接下来\n才要正式开始哦。', /*text_2*/'状态越来\n越好了哦。', /*voice_cue_1*/'vo_minigame_1013_icon_1_002_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_002_001', /*play_time*/3000, /*priority*/2);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/2, /*action_type*/2, /*action_param*/5000, /*face_icon_type*/2, /*text_1*/'嘻嘻，真是不错的\n进展呢。', /*text_2*/'喂喂喂，\n应该还能继续吧？', /*voice_cue_1*/'vo_minigame_1013_icon_1_003_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_003_001', /*play_time*/3000, /*priority*/2);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/3, /*action_type*/2, /*action_param*/10000, /*face_icon_type*/3, /*text_1*/'真是非常\n精彩的记录。', /*text_2*/'嘿嘿，你们\n挺有能耐的嘛！', /*voice_cue_1*/'vo_minigame_1013_icon_1_004_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_004_001', /*play_time*/3000, /*priority*/2);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/4, /*action_type*/3, /*action_param*/10000, /*face_icon_type*/3, /*text_1*/'势头真是\n强劲呢。', /*text_2*/'我们可还没\n停下来呢！', /*voice_cue_1*/'vo_minigame_1013_icon_1_005_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_005_001', /*play_time*/3000, /*priority*/2);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/5, /*action_type*/3, /*action_param*/10000, /*face_icon_type*/3, /*text_1*/'还可以继续前进。\n跟紧我。', /*text_2*/'看着吧！\n真琴小队要大展拳脚了！', /*voice_cue_1*/'vo_minigame_1013_icon_1_005_002', /*voice_cue_2*/'vo_minigame_1013_icon_2_005_002', /*play_time*/3000, /*priority*/2);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/6, /*action_type*/3, /*action_param*/10000, /*face_icon_type*/3, /*text_1*/'是时候让惠理子小队\n大展身手了！', /*text_2*/'哇哦哦哦！\n状态超棒！', /*voice_cue_1*/'vo_minigame_1013_icon_1_005_003', /*voice_cue_2*/'vo_minigame_1013_icon_2_005_003', /*play_time*/3000, /*priority*/2);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/7, /*action_type*/4, /*action_param*/0, /*face_icon_type*/3, /*text_1*/'接下来，我们将进入\n前所未有的领域！', /*text_2*/'真想看看你们\n能走多远！', /*voice_cue_1*/'vo_minigame_1013_icon_1_006_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_006_001', /*play_time*/3000, /*priority*/2);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/8, /*action_type*/5, /*action_param*/1, /*face_icon_type*/4, /*text_1*/'真是麻烦啊……', /*text_2*/'别放弃啊。', /*voice_cue_1*/'vo_minigame_1013_icon_1_007_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_007_001', /*play_time*/1000, /*priority*/3);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/9, /*action_type*/5, /*action_param*/1, /*face_icon_type*/4, /*text_1*/'切忌疏忽大意。', /*text_2*/'真是吓了我一跳！', /*voice_cue_1*/'vo_minigame_1013_icon_1_007_002', /*voice_cue_2*/'vo_minigame_1013_icon_2_007_002', /*play_time*/1000, /*priority*/3);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/10, /*action_type*/5, /*action_param*/1, /*face_icon_type*/4, /*text_1*/'真可恶……', /*text_2*/'不要示弱。', /*voice_cue_1*/'vo_minigame_1013_icon_1_007_003', /*voice_cue_2*/'vo_minigame_1013_icon_2_007_003', /*play_time*/1000, /*priority*/3);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/11, /*action_type*/6, /*action_param*/99, /*face_icon_type*/3, /*text_1*/'人数很壮观呢。', /*text_2*/'真琴小队集合！', /*voice_cue_1*/'vo_minigame_1013_icon_1_008_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_008_001', /*play_time*/1500, /*priority*/4);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/12, /*action_type*/6, /*action_param*/99, /*face_icon_type*/3, /*text_1*/'欢迎来到惠理子小队。', /*text_2*/'我们一起协作吧！', /*voice_cue_1*/'vo_minigame_1013_icon_1_008_002', /*voice_cue_2*/'vo_minigame_1013_icon_2_008_002', /*play_time*/1500, /*priority*/4);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/13, /*action_type*/8, /*action_param*/0, /*face_icon_type*/6, /*text_1*/'就交给\n小七七香吧。', /*text_2*/'为大家加油！', /*voice_cue_1*/'vo_minigame_1013_icon_1_020_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_020_001', /*play_time*/3000, /*priority*/1);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/14, /*action_type*/9, /*action_param*/0, /*face_icon_type*/7, /*text_1*/'哈哈哈！\n包在我身上！', /*text_2*/'交给我吧。', /*voice_cue_1*/'vo_minigame_1013_icon_1_022_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_022_001', /*play_time*/3000, /*priority*/1);
INSERT INTO `nbb_face_icon_action_data` VALUES (/*id*/15, /*action_type*/10, /*action_param*/0, /*face_icon_type*/8, /*text_1*/'要继续了哦。', /*text_2*/'好了，走吧。', /*voice_cue_1*/'vo_minigame_1013_icon_1_023_001', /*voice_cue_2*/'vo_minigame_1013_icon_2_023_001', /*play_time*/3000, /*priority*/1);
